        $sectionOrder=array_column($p['document']['sections'],'order','key');$rowOrder=array_column($p['document']['rows'],'order','key');usort($items,function($a,$b)use($sectionOrder,$rowOrder){$a=json_decode($a['seat_json'],true);$b=json_decode($b['seat_json'],true);return[($sectionOrder[$a['section']]??0),($rowOrder[$a['row']]??0),(float)$a['x'],$a['label']]<=>[($sectionOrder[$b['section']]??0),($rowOrder[$b['row']]??0),(float)$b['x'],$b['label']];});
        foreach($items as $i){$s=json_decode($i['seat_json'],true);$available=in_array($i['state'],['available','released'],true)&&$p['sales_status']==='open';$label=$s['section_name'].' / Row '.$s['row_name'].' / Seat '.$s['label'];$attributes=($s['wheelchair']?' · W: Wheelchair position':'').($s['companion']?' · Companion of '.$s['companion']:'').($s['restricted']?' · Restricted view':'');echo '<div data-seat-row="'.self::e($i['seat_key']).'" data-accessible="'.(($s['wheelchair']||$s['companion'])?'1':'0').'"><label><input type="checkbox" data-seat-check name="seats[]" value="'.self::e($i['seat_key']).'" '.(!$available?'disabled':'').'>'.self::e($label.' · '.$i['state'].$attributes).'</label>';if($s['description'])echo '<p>'.self::e($s['description']).'</p>';echo '<label class="commerce-category">Ticket category for '.self::e($label).'<select data-seat-category name="categories['.self::e($i['seat_key']).']" '.(!$available?'disabled':'').'>';foreach($prices[$s['zone']] as $cat=>$amount)echo '<option value="'.self::e($cat).'">'.self::e($cat.' · '.$s['zone']).' · '.self::money((int)$amount,$p['currency']).'</option>';echo '</select></label></div>';}
        echo '</div><div class="commerce-summary"><strong data-selection-count>0 seats selected</strong><p data-selection-total>Choose seats to see your total.</p><p data-selection-message role="status"></p></div><h3>Guest purchaser · test details only</h3>';self::input('customer_name','Purchaser name','text','','required maxlength="190" autocomplete="name"');self::input('customer_email','Synthetic email ending in .invalid','email','buyer@commerce.invalid','required maxlength="254" autocomplete="off"');echo '<details><summary>Add optional phone</summary><p>Only needed when testing a box-office contact workflow. Use synthetic digits.</p>';self::input('customer_phone','Phone (optional)','tel','','maxlength="40" autocomplete="off"');echo '</details><button type="submit" data-selection-continue '.($p['sales_status']!=='open'?'disabled':'').'>Hold seats & review order</button><p>All seats are held together for a limited time. Your total is confirmed by the server before any simulated payment.</p></div></form>';
