    private static function checkout():void
    {
        $id=(int)($_GET['id']??0);$token=(string)($_SESSION['commerce_orders'][self::$org.':'.$id]??'');$o=CommerceInventoryService::own(self::$db,self::$user,self::$org,$id,$token);CommerceInventoryService::availability(self::$db,self::$user,self::$org,(int)$o['performance_id']);$o=CommerceInventoryService::own(self::$db,self::$user,self::$org,$id,$token);$p=self::performanceContext((int)$o['performance_id']);echo '<h2>Order review</h2><p>'.self::e($p['title']).'</p><p>'.self::e($p['starts_at'].' · '.$p['venue']).'</p><p>Order '.self::e($o['public_reference']).' · <strong>'.self::e(str_replace('_',' ',$o['state'])).'</strong></p><p>Purchaser: '.self::e($o['customer_name']).' · '.self::e($o['customer_email']).'</p><div class="commerce-table-scroll"><table><caption>Ticket price snapshot</caption><thead><tr><th>Seat</th><th>Category</th><th>Price</th></tr></thead><tbody>';foreach(self::rows('SELECT * FROM commerce_order_lines WHERE organization_id=? AND order_id=? ORDER BY id',[self::$org,$id]) as $l)echo '<tr><td>'.self::e($l['description']).'</td><td>'.self::e($l['category']).'</td><td>'.self::money((int)$l['unit_minor'],$o['currency']).'</td></tr>';echo '</tbody></table></div>';self::totals($o);echo '<p>Hold deadline: '.self::e($o['expires_at']).' (server time). Refreshing does not extend it. The server checks expiry when payment starts.</p>';self::checkoutActions($o);
    }
    private static function totals(array $o):void
    {echo '<dl class="commerce-totals">';foreach(['subtotal'=>'Tickets','discount'=>'Discount','tax'=>'Tax','fee'=>'Order fee','total'=>'Total'] as $key=>$label)echo '<div class="'.($key==='total'?'commerce-total':'').'"><dt>'.$label.'</dt><dd>'.($key==='discount'?'−':'').self::money((int)$o[$key.'_minor'],$o['currency']).'</dd></div>';echo '</dl>';}
    private static function checkoutActions(array $o):void{echo '<p>Payment simulation is the next milestone. Expired holds are released by the server.</p><a href="'.self::e(self::url('select',['id'=>$o['performance_id']])).'">Back to seat selection</a>';}

